1	import {
2	  internalAction,
3	  internalMutation,
4	  internalQuery,
5	  ActionCtx,
6	  MutationCtx,
7	} from "./_generated/server";
8	import { v } from "convex/values";
9	import { internal } from "./_generated/api";
10	import { Doc, Id } from "./_generated/dataModel";
11	import { embedText } from "./openaiClient";
12	
13	// A person's memories are derived from their context, which every write path
14	// clamps to 4000 characters -- but a person edited over years accumulates
15	// lines faster than the blob does, because nothing is ever deleted. The cap
16	// is what keeps the dedupe read and the delete cascade bounded.
17	export const MAX_MEMORIES_PER_PERSON = 200;
18	
19	// Same schedule people.embed uses: index 0 is the delay before retry attempt
20	// 1, index 1 before attempt 2, then we give up.
21	const EMBED_RETRY_DELAYS_MS = [30_000, 5 * 60_000];
22	
23	// The embeddings request has its own size ceiling, and one memory line can be
24	// the whole 4000-character context blob.
25	const MAX_EMBED_INPUT_LENGTH = 8000;
26	
27	// Smaller than people.ts's 500: this page also schedules one embed action per
28	// line it inserts, so a large page would queue thousands of paid calls in one
29	// transaction.
30	const BACKFILL_PAGE_SIZE = 100;
31	
32	// How many unembedded rows one sweep pass repairs.
33	const EMBED_SWEEP_LIMIT = 200;
34	
35	// appendContext has always joined entries with a newline, so splitting on one
36	// is faithful to the boundaries the user actually wrote -- which is also what
37	// makes the migration in backfillMemories the same operation as a live write.
38	function splitMemoryLines(context: string | undefined): string[] {
39	  if (context === undefined) {
40	    return [];
41	  }
42	  return context
43	    .split("\n")
44	    .map((line) => line.trim())
45	    .filter((line) => line !== "");
46	}
47	
48	// Additive on purpose. A note the user later edits away keeps its memory row:
49	// the display copy is what they curate, and forgetting a thing they once
50	// wrote is the one failure this whole plan exists to prevent. The cost is
51	// that a typo fixed in the note leaves the typo'd line searchable.
52	export async function syncMemories(
53	  ctx: MutationCtx,
54	  args: {
55	    userId: string;
56	    personId: Id<"people">;
57	    context: string | undefined;
58	    createdAt: number;
59	  },
60	): Promise<void> {
61	  const lines = splitMemoryLines(args.context);
62	  if (lines.length === 0) {
63	    return;
64	  }
65	  const existing = await ctx.db
66	    .query("memories")
67	    .withIndex("by_person", (q) => q.eq("personId", args.personId))
68	    .take(MAX_MEMORIES_PER_PERSON);
69	  const seen = new Set(existing.map((memory) => memory.text));
70	  let room = MAX_MEMORIES_PER_PERSON - existing.length;
71	  for (const text of lines) {
72	    if (room === 0) {
73	      return;
74	    }
75	    if (seen.has(text)) {
76	      continue;
77	    }
78	    seen.add(text);
79	    room--;
80	    const memoryId = await ctx.db.insert("memories", {
81	      userId: args.userId,
82	      personId: args.personId,
83	      text,
84	      createdAt: args.createdAt,
85	    });
86	    await ctx.scheduler.runAfter(0, internal.memories.embed, { memoryId });
87	  }
88	}
89	
90	// Bounded by the same cap the insert path enforces, so one take is the whole
91	// set. Orphaned rows would keep matching in the vector index for a person the
92	// user deleted.
93	export async function deleteMemories(
94	  ctx: MutationCtx,
95	  personId: Id<"people">,
96	): Promise<void> {
97	  const rows = await ctx.db
98	    .query("memories")
99	    .withIndex("by_person", (q) => q.eq("personId", personId))
100	    .take(MAX_MEMORIES_PER_PERSON);
101	  for (const row of rows) {
102	    await ctx.db.delete("memories", row._id);
103	  }
104	}
105	
106	// ------------------------------------------------------------- embeddings
107	
108	export const getMemoryInternal = internalQuery({
109	  args: { id: v.id("memories") },
110	  handler: async (ctx, args) => {
111	    return await ctx.db.get("memories", args.id);
112	  },
113	});
114	
115	export const saveMemoryEmbedding = internalMutation({
116	  args: {
117	    id: v.id("memories"),
118	    embedding: v.array(v.float64()),
119	    embeddedText: v.string(),
120	  },
121	  returns: v.null(),
122	  handler: async (ctx, args) => {
123	    const memory = await ctx.db.get("memories", args.id);
124	    if (memory === null) {
125	      return null;
126	    }
127	    await ctx.db.patch("memories", args.id, {
128	      embedding: args.embedding,
129	      embeddedText: args.embeddedText,
130	    });
131	    return null;
132	  },
133	});
134	
135	// Shared by the embed action and the sweep (guidelines: do not call an action
136	// from an action in the same runtime; share a helper instead).
137	async function embedMemory(
138	  ctx: ActionCtx,
139	  memoryId: Id<"memories">,
140	): Promise<void> {
141	  const memory: Doc<"memories"> | null = await ctx.runQuery(
142	    internal.memories.getMemoryInternal,
143	    { id: memoryId },
144	  );
145	  if (memory === null) {
146	    return;
147	  }
148	  // The line itself is the embed input: that is the whole point of a memory
149	  // row, so no surrounding card fields are mixed back in.
150	  const text = memory.text.slice(0, MAX_EMBED_INPUT_LENGTH);
151	  if (memory.embedding !== undefined && memory.embeddedText === text) {
152	    return;
153	  }
