// Live recall for people:ask, run by hand rather than in CI: model output is
// not deterministic enough to gate a merge on, but "did the last prompt edit
// make this better or worse" is unanswerable without a number.
//
//   OPENAI_API_KEY=sk-... node scripts/eval-ask.ts
//   ASK_BASE_URL=https://api.interfaze.ai ASK_API_KEY=... ASK_MODEL=interfaze-beta \
//     node scripts/eval-ask.ts
//
// Node 24+ strips the types, so there is nothing to install. It talks to the
// provider directly and never touches a Convex deployment, because the
// fixtures carry their own prebuilt networks.

import { ASK_FIXTURES, type AskFixture } from "../src/askFixtures.ts";
import { askNetwork, type AskAnswer } from "../convex/openaiClient.ts";

// Each fixture runs this many times. One sample cannot tell a prompt that is
// reliably right from one that got lucky, and that difference is the only
// reason to measure at all.
const RUNS_PER_FIXTURE = Number(process.env.EVAL_RUNS ?? "3");

type Outcome = {
  fixture: AskFixture;
  run: number;
  hit: boolean;
  detail: string;
};

function grade(fixture: AskFixture, answer: AskAnswer): {
  hit: boolean;
  detail: string;
} {
  const got = answer.matches.map((match) => `#${match.ref} ${match.kind}`);
  if (fixture.expectClarification === true) {
    const asked = answer.clarifyingQuestion !== undefined;
    return {
      hit: asked && answer.matches.length === 0,
      detail: asked ? `asked: ${answer.clarifyingQuestion}` : `guessed: ${got.join(", ")}`,
    };
  }
  if (fixture.expected.length === 0) {
    return {
      hit: answer.matches.length === 0,
      detail: answer.matches.length === 0 ? "named nobody" : `named ${got.join(", ")}`,
    };
  }
  // Kind matters as much as identity: a bridge returned as a direct match is
  // the specific failure this feature is most likely to be trusted through.
  const missing = fixture.expected.filter(
    (want) =>
      !answer.matches.some(
        (match) => match.ref === want.ref && match.kind === want.kind,
      ),
  );
  return {
    hit: missing.length === 0,
    detail:
      missing.length === 0
        ? `found ${got.join(", ")}`
        : `missing ${missing.map((m) => `#${m.ref} ${m.kind}`).join(", ")}; got ${got.join(", ") || "nothing"}`,
  };
}

const outcomes: Outcome[] = [];
for (const fixture of ASK_FIXTURES) {
  for (let run = 1; run <= RUNS_PER_FIXTURE; run++) {
    try {
      const answer = await askNetwork(fixture.query, fixture.network, []);
      const { hit, detail } = grade(fixture, answer);
      outcomes.push({ fixture, run, hit, detail });
    } catch (error) {
      // A provider failure is a failed run, not a crashed eval: the other
      // cases still carry information.
      outcomes.push({
        fixture,
        run,
        hit: false,
        detail: `error: ${error instanceof Error ? error.message : String(error)}`,
      });
    }
  }
}

let passed = 0;
for (const fixture of ASK_FIXTURES) {
  const runs = outcomes.filter((outcome) => outcome.fixture === fixture);
  const hits = runs.filter((outcome) => outcome.hit).length;
  passed += hits;
  console.log(`\n${hits}/${runs.length}  ${fixture.name}`);
  console.log(`         query: ${fixture.query}`);
  console.log(`         why it matters: ${fixture.why}`);
  for (const run of runs) {
    console.log(`         run ${run.run}: ${run.hit ? "ok" : "MISS"} -- ${run.detail}`);
  }
}

const total = outcomes.length;
console.log(
  `\nrecall ${passed}/${total} (${Math.round((passed / total) * 100)}%) over ${ASK_FIXTURES.length} cases x ${RUNS_PER_FIXTURE} runs`,
);
// Non-zero on any miss, so this can gate a prompt change without anyone
// having to read the output.
process.exit(passed === total ? 0 : 1);

// The evaluation set for people:ask, shared on purpose: CI checks the
// contract against a mocked provider, and scripts/eval-ask.ts runs these same
// cases against the live model to report recall. Two copies of the cases
// would drift, and then neither number would mean anything.
//
// Each network is a prebuilt dossier block in the exact shape buildDossier
// produces, so a fixture needs no database.

export type AskFixture = {
  name: string;
  network: string;
  query: string;
  // Which refs the model should name, and how. An empty list means the right
  // answer is to name nobody.
  expected: Array<{ ref: number; kind: "direct" | "bridge" }>;
  // True when the honest answer is a question rather than a guess.
  expectClarification?: boolean;
  why: string;
};

const NETWORK = [
  `#1 Ada Lovelace | Compiler engineer at Analytical Engines | Sai Gon | x
Building symbolic math tools.
- 2026-05-02: met at the Founder Inc dinner
- 2026-05-04: works on an infinite-context-window database, says the index is the hard part`,
  `#2 Grace Hopper | Designer at Pixel Foundry | Ha Noi | instagram
- 2026-04-11: does brand identity work, mostly for restaurants`,
  `#3 Alan Turing | Analyst at Y Combinator | San Francisco | linkedin
- 2026-06-01: screens applications for the winter batch`,
  `#4 Katherine Johnson | Ha Noi | instagram
- 2026-03-20: chi ay lam ve du lieu ve khi hau, dang tim nguoi lam backend`,
].join("\n\n");

export const ASK_FIXTURES: AskFixture[] = [
  {
    name: "direct match on a memory line, not a card field",
    network: NETWORK,
    query: "do I know anyone with database experience",
    expected: [{ ref: 1, kind: "direct" }],
    why: "Nothing in Ada's card says 'database'. Only the note does, which is the whole point of the memory substrate.",
  },
  {
    name: "bridge when nobody fits directly",
    network: NETWORK,
    query: "I need to talk to a startup founder",
    expected: [{ ref: 3, kind: "bridge" }],
    why: "Nobody here is a founder. Alan screens YC applications, so he is a route to one -- and it must come back labelled bridge, not dressed up as a direct match.",
  },
  {
    name: "Vietnamese note answers an English query",
    network: NETWORK,
    query: "who works on climate data",
    expected: [{ ref: 4, kind: "direct" }],
    why: "The note is unaccented Vietnamese and the question is English. The user's network is mostly Vietnamese, so this is the common case, not an edge one.",
  },
  {
    name: "a vague ask gets a question, not a guess",
    network: NETWORK,
    query: "who should I talk to",
    expected: [],
    expectClarification: true,
    why: "There is no need stated. Guessing here is how the feature earns distrust.",
  },
  {
    name: "nobody matches and nobody is invented",
    network: NETWORK,
    query: "do I know a commercial airline pilot",
    expected: [],
    why: "Empty is the correct answer. A model that pads this with the nearest person is worse than one that says nothing.",
  },
];

